CREATE OR REPLACE FUNCTION private.guard_listing_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not private.is_admin() then

    if new.seller_id is distinct from old.seller_id then
      raise exception 'Modification du vendeur interdite';
    end if;

    if new.status is distinct from old.status then
      raise exception 'Modification du statut interdite';
    end if;

    if new.views_count is distinct from old.views_count then
      raise exception 'Modification des vues interdite';
    end if;

    if new.published_at is distinct from old.published_at then
      raise exception 'Modification de publication interdite';
    end if;

    if new.rejection_reason is distinct from old.rejection_reason then
      raise exception 'Modification du motif de rejet interdite';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_listing_owner_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select private.is_admin()) then return new; end if;
  if new.seller_id is distinct from old.seller_id
     or new.views_count is distinct from old.views_count
     or new.published_at is distinct from old.published_at
     or new.rejection_reason is distinct from old.rejection_reason then
    raise exception 'seller cannot modify system-managed listing fields';
  end if;
  if new.status is distinct from old.status then
    if old.status in ('draft'::public.listing_status, 'rejected'::public.listing_status)
       and new.status = 'pending'::public.listing_status then
      null;
    else raise exception 'seller cannot perform this listing status transition';
    end if;
  end if;
  return new;
end; $function$
